set local role authenticated;
select set_config('test.survey',jsonb_build_object('request_id','17600000-0000-4000-8000-000000000050','id',null,'class_id','17600000-0000-4000-8000-000000000010','title','TEST-NPS-SURVEY','status','open','expires_at',now()+interval '14 days','expected_updated_at',null)::text,true);
select throws_ok($$select public.save_b2c_nps_survey(current_setting('test.survey')::jsonb||jsonb_build_object('expires_at',now()-interval '1 day'))$$,'22023',null,'Past expiry rejected');
select throws_ok($$select public.save_b2c_nps_survey(current_setting('test.survey')::jsonb||jsonb_build_object('expires_at',now()+interval '91 days'))$$,'22023',null,'Unbounded expiry rejected');
