select is(public.save_b2c_nps_survey(current_setting('test.survey')::jsonb)::text,current_setting('test.survey_id'),'Create retry returns same survey');
select throws_ok($$select public.save_b2c_nps_survey(current_setting('test.survey')::jsonb||'{"title":"changed"}')$$,'22023',null,'Changed request rejected');
select throws_ok($$select public.save_b2c_nps_survey(current_setting('test.survey')::jsonb||jsonb_build_object('request_id',gen_random_uuid()))$$,'22023',null,'Only one survey per class');
