set local role anon;
select is(public.read_public_b2c_nps(lpad('45',64,'0'))->>'state','closed','Closed survey cannot be filled');
select throws_ok($$select public.submit_public_b2c_nps(lpad('45',64,'0'),jsonb_build_object('request_id',gen_random_uuid(),'score',9))$$,'22023',null,'Closed submission rejected');
reset role;
