set local role anon;
select is(public.read_public_b2c_nps(lpad('45',64,'0'))->>'state','invalid','Revoked link invalid');
select throws_ok($$select public.submit_public_b2c_nps(lpad('45',64,'0'),jsonb_build_object('request_id',gen_random_uuid(),'score',9))$$,'22023',null,'Revoked submission rejected');
reset role;
update public.b2c_nps_invitations set revoked=false,token_hash=encode(extensions.digest(repeat('a',64),'sha256'),'hex') where parent_id='17600000-0000-4000-8000-000000000045';
