insert into public.b2c_student_parents(parent_id,student_id) values('17600000-0000-4000-8000-000000000045','17600000-0000-4000-8000-000000000020');
alter table public.b2c_nps_responses add constraint test_nps_failure check(reason<>'FAIL-RESPONSE') not valid;
set local role anon;
select throws_ok($$select public.submit_public_b2c_nps(repeat('a',64),jsonb_build_object('request_id','17600000-0000-4000-8000-000000000070','score',9,'reason','FAIL-RESPONSE'))$$,'23514',null,'Storage failure rejects response atomically');
reset role;
select is((select count(*)::integer from public.b2c_nps_responses where request_id='17600000-0000-4000-8000-000000000070'),0,'Failed response leaves no partial record');
set local role anon;
select lives_ok($$select public.submit_public_b2c_nps(repeat('a',64),jsonb_build_object('request_id','17600000-0000-4000-8000-000000000070','score',9,'reason','FIXED'))$$,'Failed request can be retried successfully');
reset role;
select * from finish();
